<?php
declare(strict_types=1);
if (is_file(__DIR__.'/groq_config.php')) require_once __DIR__.'/groq_config.php';
function groq_key(): string { return (string)(getenv('GROQ_API_KEY') ?: (defined('GROQ_API_KEY') ? GROQ_API_KEY : '')); }
function groq_request(string $url, array $headers, array $options=[]): array { $ch=curl_init($url); $ca=__DIR__.'/../certs/cacert.pem'; $tls=is_file($ca)?[CURLOPT_CAINFO=>$ca,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]:[]; curl_setopt_array($ch,$options+$tls+[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>180]); $body=curl_exec($ch); $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); $err=curl_error($ch); curl_close($ch); if($body===false||$err) throw new RuntimeException('Groq request failed: '.$err); $data=json_decode($body,true); if($code<200||$code>=300) throw new RuntimeException($data['error']['message']??('Groq returned HTTP '.$code)); return is_array($data)?$data:[]; }
function groq_transcribe(string $path, ?string $language=null): string { $key=groq_key(); if($key==='')throw new RuntimeException('GROQ_API_KEY is not configured in Wamp.'); $language=$language?:null; $fields=['file'=>new CURLFile($path),'model'=>$language==='ar'?'whisper-large-v3':'whisper-large-v3-turbo','response_format'=>'json','temperature'=>'0']; if($language)$fields['language']=$language; if($language==='ar')$fields['prompt']='هذا تسجيل اجتماع عمل تقني. حافظ على أسماء المنتجات والبرامج والمصطلحات التقنية كما نُطقت، مثل API وSQL وPHP وMySQL وGroq وWhisper وMAT وWampServer، ولا تترجم أسماء الأشخاص أو الشركات.'; $data=groq_request('https://api.groq.com/openai/v1/audio/transcriptions',['Authorization: Bearer '.$key],[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$fields]); return trim((string)($data['text']??'')); }
function groq_tasks(string $transcript, ?string $language=null): array { $key=groq_key(); if($key==='') throw new RuntimeException('GROQ_API_KEY is not configured in Wamp.'); $language=$language?: (preg_match('/[\x{0600}-\x{06FF}]/u',$transcript)?'ar':'en'); $outputLanguage=$language==='ar'?'Arabic (العربية)':'the transcript language'; $payload=['model'=>'openai/gpt-oss-20b','temperature'=>0,'response_format'=>['type'=>'json_object'],'messages'=>[['role'=>'system','content'=>'Extract only actionable work items from the meeting transcript. Write task titles and descriptions in '.$outputLanguage.'. Keep priority values exactly in English as urgent, important, or normal. Return JSON exactly as {"tasks":[{"title":"short task","description":"specific outcome","priority":"urgent|important|normal","due_date":"YYYY-MM-DD or null"}]}. Do not invent owners or dates. If there are no actionable items return an empty tasks array.'],['role'=>'user','content'=>$transcript]]]; $data=groq_request('https://api.groq.com/openai/v1/chat/completions',['Authorization: Bearer '.$key,'Content-Type: application/json'],[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload)]); $content=$data['choices'][0]['message']['content']??'{"tasks":[]}'; $parsed=json_decode($content,true); return is_array($parsed['tasks']??null)?$parsed['tasks']:[]; }
